attempts.sql:
SELECT DISTINCT file_id AS file_path
FROM code.imports
WHERE imported_file_id IN (
    SELECT file_id FROM code.files WHERE module = '_compat'
) AND imported_file_id IN (
    SELECT file_id FROM code.files WHERE module = 'utils'
) AND file_id NOT IN (
    SELECT imported_file_id FROM code.imports
    WHERE imported_file_id IN (
        SELECT file_id FROM code.files WHERE module = 'core'
    )
)
AND file_id LIKE 'src/click/%'
ORDER BY file_path;

